const results = [];

for (const input of $input.all()) {
  const d = input.json.output ?? input.json;
  const raw = String(d.Items ?? d.items ?? "");

  const regex =
    /Item:\s*(.*?)\s+Quantity:\s*(\d+(?:\.\d+)?)\s+Price:\s*₹?\s*([\d,]+(?:\.\d+)?)/gi;

  const products = [];
  let match;

  while ((match = regex.exec(raw)) !== null) {
    products.push({
      item: match[1].trim(),
      quantity: Number(match[2]),
      price: Number(match[3].replace(/,/g, "")),
    });
  }

  for (let index = 0; index < products.length; index++) {
    const p = products[index];

    results.push({
      json: {
        "Date": d.Date ?? d.date ?? "",
        "From": d.From ?? d.from ?? "",
        "Billed to": d["Billed to"] ?? d.Billed_to ?? "",
        "Item": p.item,
        "Quantity": p.quantity,
        "Price": p.price,
        "Total Amount": index === 0 ? (d["Total Amount"] ?? d.totalAmount ?? "") : "",
        "Balance Due": index === 0 ? (d["Balance Due"] ?? d.balanceDue ?? "") : "",
      },
    });
  }
}

return results;

const rows = $("Code in JavaScript").all().map(i => i.json);

if (rows.length === 0) {
  throw new Error("No invoice rows found from Code in JavaScript.");
}

const first = rows[0];

const esc = (v) => String(v ?? "").replace(/[&<>"']/g, c => ({
  "&": "&amp;",
  "<": "&lt;",
  ">": "&gt;",
  '"': "&quot;",
  "'": "&#39;"
}[c]));

const company = first["Billed to"] || "Unknown Company";
const date = first["Date"] || "";
const sender = first["From"] || "";
const total = first["Total Amount"] ?? "";
const balance = first["Balance Due"] ?? "";

const itemRows = rows.map((r, i) => `
<tr>
  <td>${i + 1}</td>
  <td>${esc(r["Item"])}</td>
  <td>${esc(r["Quantity"])}</td>
  <td>₹${esc(r["Price"])}</td>
</tr>`).join("");

const message = `
<p>Hello Sir,</p>
<p>A new invoice has been processed successfully.</p>
<p>
<strong>Company:</strong> ${esc(company)}<br>
<strong>Date:</strong> ${esc(date)}<br>
<strong>From:</strong> ${esc(sender)}<br>
<strong>Total Amount:</strong> ₹${esc(total)}<br>
<strong>Balance Due:</strong> ₹${esc(balance)}
</p>
<h3>Invoice Items</h3>
<table border="1" cellpadding="6" cellspacing="0">
<tr><th>No.</th><th>Item</th><th>Quantity</th><th>Price</th></tr>
${itemRows}
</table>
<p>All invoice items have been saved to Google Sheets.</p>
<p>Regards,<br>Invoice Automation System</p>`;

return [{
  json: {
    subject: `New Invoice Processed - ${company}`,
    message: message
  }
}];
